    cursor: pointer;
    padding: 0.4rem 0.5rem;
    border-radius: 4px;
}

.channel-item:hover {
    background: #f5f5f5;
}

.channel-item input[type="checkbox"] {
    width: 16px;
    height: 16px;
    accent-color: #1976d2;
}

.button-group {
