toolArgs.file_text:
.appearance-section {
    max-width: 600px;
}

.setting-group {
    margin-bottom: 1.5rem;
}

.setting-group h3 {
    font-size: 1rem;
    margin-bottom: 0.5rem;
}

.radio-group {
    display: flex;
    gap: 1.25rem;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
    font-size: 0.95rem;
}

.radio-item input[type="radio"] {
    accent-color: #1976d2;
}

.setting-group select {
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
    min-width: 200px;
}

.toggle-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
    font-size: 0.95rem;
}

.toggle-item input[type="checkbox"] {
    width: 18px;
    height: 18px;
    accent-color: #1976d2;
}

.preview-area {
    margin-bottom: 1.5rem;
}

.preview-area h3 {
    font-size: 1rem;
    margin-bottom: 0.5rem;
}

.preview-box {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1.25rem;
    transition: all 0.2s;
}

.preview-box.theme-light {
    background: #ffffff;
    color: #333;
}

.preview-box.theme-dark {
    background: #1e1e1e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-box.theme-system {
    background: #f5f5f5;
    color: #333;
}

.preview-box.font-small {
    font-size: 0.8rem;
}

.preview-box.font-medium {
    font-size: 0.95rem;
}

.preview-box.font-large {
    font-size: 1.15rem;
}

.preview-box.compact {
    padding: 0.6rem 0.8rem;
    line-height: 1.3;
}

.preview-header {
    font-weight: 700;
    font-size: 1.1em;
    margin-bottom: 0.5rem;
}

.preview-text {
    margin: 0 0 0.75rem;
    opacity: 0.85;
}

.preview-button {
    padding: 0.4rem 0.8rem;
    border: none;
    border-radius: 4px;
    background: #1976d2;
    color: white;
    cursor: pointer;
    font-size: 0.9em;
}

.theme-dark .preview-button {
    background: #64b5f6;
    color: #1e1e1e;
}

.button-group {
    margin-top: 1.5rem;
}

.btn-primary {
    background: #1976d2;
    color: white;
    border: none;
    padding: 0.6rem 1.2rem;
    border-radius: 4px;
    cursor: pointer;
    font-weight: 600;
}

.btn-primary:hover {
    background: #1565c0;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
}

.toast.success {
    background: #e8f5e9;
    color: #2e7d32;
    border: 1px solid #a5d6a7;
}

